mode = (sys.argv[1] if len(sys.argv) > 1 else "dry").strip()
if mode not in ("dry", "apply"):
    raise SystemExit("режим: dry | apply")
dry = mode == "dry"
factory = build_references_uow_factory(build_engine(os.environ["ERP_DATABASE_URL"]))
now = moscow_now()


def run(rows, label, *, create):
    def call(dry_run):
        return import_rows("prov", factory(), [ImportRowIn(fields=r["fields"], old=r["old"]) for r in rows], ACTOR, now,
                           dry_run=dry_run, source="erp").model_dump()

    data = call(True)
    # a fill must find its row; a new row must not touch an existing one — otherwise the whole group stops
    if (data["created"] and not create) or (create and data["updated"]):
        print(f"== {label}: СТОП — создано {len(data['created'])}, обновлено {len(data['updated'])}; ничего не записано")
        return data
    if not dry:
        data = call(False)
    print(f"== {label}: строк {len(rows)} → создано {len(data['created'])}, обновлено {len(data['updated'])}, "
          f"без изменений {data['unchanged']}, отказ {len(data['refused'])}")
    for item in data["refused"][:20]:
        print("   отказ:", item)
    return data


run(PAYLOAD["fill"], "Стандарт коаксиальных кабелей", create=False)
print("ИТОГО", "(проверка, ничего не записано)" if dry else "(записано)")
